"""Read bounded library and filesystem facts; no application or input parsing."""

import hashlib
import importlib
import importlib.metadata
import json
import stat
import sys
from pathlib import Path

result = {
    "python": sys.version,
    "executable": sys.executable,
    "libraries": {},
    "files": {},
}
for name, package in (
    ("sqlite3", None),
    ("soundfile", "soundfile"),
    ("lxml.etree", "lxml"),
    ("PIL.features", "pillow"),
):
    observed = {}
    if package:
        try:
            observed["distribution_version"] = importlib.metadata.version(package)
        except importlib.metadata.PackageNotFoundError:
            observed["status"] = "distribution_absent"
            result["libraries"][name] = observed
            continue
    try:
        module = importlib.import_module(name)
        observed["module_file"] = module.__file__
        if name == "sqlite3":
            import _sqlite3

            observed["binding_file"] = _sqlite3.__file__
            observed["sqlite_version"] = module.sqlite_version
            with module.connect(":memory:") as connection:
                observed["compile_options"] = [
                    r[0] for r in connection.execute("PRAGMA compile_options")
                ]
        elif name == "soundfile":
            observed["libsndfile_version"] = module.__libsndfile_version__
            observed["selected_library"] = module._libname
        elif name == "lxml.etree":
            observed["libxml_runtime"] = module.LIBXML_VERSION
            observed["libxml_compiled"] = module.LIBXML_COMPILED_VERSION
        else:
            observed["libtiff_enabled"] = module.check_codec("libtiff")
            observed["libtiff_version"] = module.version_codec("libtiff")
        observed["status"] = "observed"
    except (ImportError, OSError, AttributeError, RuntimeError) as error:
        observed["status"] = "import_or_version_observation_failed"
        observed["error_type"] = type(error).__name__
    result["libraries"][name] = observed

for path in (
    "/etc/fstab",
    "/etc",
    "/usr/bin/mount",
    "/usr/bin/umount",
    "/usr/bin/cp",
    "/usr/bin/mv",
    "/usr/bin/install",
    "/app",
    "/app/Databases",
    "/app/Config_Files",
    "/app/tldw_Server_API/Config_Files",
    "/sbin",
    "/sbin/fs.d",
    "/sbin/fs",
):
    p = Path(path)
    try:
        info = p.stat()
        row = {
            "uid": info.st_uid,
            "gid": info.st_gid,
            "mode": oct(stat.S_IMODE(info.st_mode)),
            "kind": "directory" if p.is_dir() else "file",
            "resolved_path": str(p.resolve()),
        }
        if p.is_file():
            raw = p.read_bytes()
            row["sha256"] = hashlib.sha256(raw).hexdigest()
            if path == "/etc/fstab":
                row["text"] = raw.decode()
        result["files"][path] = row
    except FileNotFoundError:
        result["files"][path] = {"status": "absent"}

result["mount_helper_inventory"] = {}
for directory in ("/sbin", "/sbin/fs.d", "/sbin/fs"):
    p = Path(directory)
    result["mount_helper_inventory"][directory] = (
        sorted(str(child) for child in p.glob("mount.*")) if p.is_dir() else []
    )

mapped = sorted(
    {
        line.split(maxsplit=5)[-1].strip()
        for line in Path("/proc/self/maps").read_text().splitlines()
        if len(line.split(maxsplit=5)) == 6
        and any(
            token in line
            for token in (
                "sqlite",
                "sndfile",
                "lxml",
                "libxml",
                "libtiff",
                "PIL/",
                "pillow.libs",
            )
        )
    }
)
result["mapped_library_sha256"] = {
    name: hashlib.sha256(Path(name).read_bytes()).hexdigest()
    for name in mapped
    if name.startswith("/") and Path(name).is_file()
}
result["diagnostic_process_status"] = {
    line.split(":", 1)[0]: line.split(":", 1)[1].strip()
    for line in Path("/proc/self/status").read_text().splitlines()
    if line.split(":", 1)[0]
    in {"Uid", "Gid", "CapInh", "CapPrm", "CapEff", "CapBnd", "NoNewPrivs", "Seccomp"}
}
result["application_file_sha256"] = {}
for relative in (
    "app/core/DB_Management/sqlite_schema_helpers.py",
    "app/core/Flashcards/apkg_importer.py",
    "app/core/Ingestion_Media_Processing/Audio/Audio_Streaming_Unified.py",
):
    for base in [
        Path("/app/tldw_Server_API"),
        *Path("/opt/tldw-venv/lib").glob("python*/site-packages/tldw_Server_API"),
    ]:
        p = base / relative
        if p.is_file():
            result["application_file_sha256"][str(p)] = hashlib.sha256(
                p.read_bytes()
            ).hexdigest()
result["imported_ml_modules"] = sorted(
    name
    for name in sys.modules
    if name.split(".", 1)[0]
    in {"nltk", "torch", "nemo", "lightning", "transformers", "chromadb"}
)
result["limits"] = [
    "Isolated offline diagnostic process, not production entrypoint or deployment privileges.",
    "No application/model execution, user media/database parsing, mount operation or exploit test.",
    "Filesystem facts apply to this candidate without operator volume/config overrides.",
]
print(json.dumps(result, indent=2, sort_keys=True))

